export function Cache({
  keyName = "{{keyName}}",
  state = "{{state}}",
  accent = "{{accent}}",
  showLatency = {{showLatency}},
}) {
  const results = {
    hit: `HIT \u2014 served from cache${showLatency ? ", 4ms" : ""}`,
    miss: `MISS \u2014 fetched from origin, cache populated${showLatency ? ", 210ms" : ""}`,
    stale: `STALE \u2014 served stale, revalidating in background${showLatency ? ", 4ms" : ""}`,
  };
  const node = (active) => ({ flex: 1, textAlign: "center", padding: "10px 4px", borderRadius: 8, fontSize: 11, fontWeight: 700, background: active ? accent : "#24143010" });
  return (
    <div role="img" aria-label={`Cache ${state} for ${keyName}`} style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>{keyName}</p>
      <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 12 }}>
        <span style={node(false)}>Client</span>
        <span style={{ color: "#24143060" }}>&rarr;</span>
        <span style={node(state === "hit" || state === "stale")}>Cache</span>
        <span style={{ color: "#24143060", opacity: state === "miss" ? 1 : .2 }}>&rarr;</span>
        <span style={node(state === "miss")}>Origin</span>
      </div>
      <p style={{ margin: 0, fontSize: 12, fontWeight: 600 }}>{results[state]}</p>
    </div>
  );
}
